class Fichier {
public:
    explicit Fichier(const std::string& chemin)
        : flux(chemin) {}
    bool ouvert() const { return flux.is_open(); }
private:
    std::ifstream flux;
};

class Forme {
public:
    virtual ~Forme() = default;
    virtual double aire() const = 0;
};

class Cercle : public Forme {
public:
    explicit Cercle(double r) : rayon(r) {}
    double aire() const override { return 3.14159 * rayon * rayon; }
private:
    double rayon;
};

